def _adapter_state(model):
    return {
        name: {"a": layer.a.detach().clone(), "b": layer.b.detach().clone(), "rank": layer.rank, "alpha": layer.alpha}
        for name, layer in model.named_modules()
        if isinstance(layer, LoRALinear)
    }
